SELECT 'UNCHANGED_ROW_compliance.source_facts_11' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A04-P04' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART04' AND legal_reference IS NOT DISTINCT FROM 'Artículo 4, apartado 4' AND source_fact_text IS NOT DISTINCT FROM 'Las API que proporcionen acceso a los datos estáticos, históricos y observados de desplazamientos y tráfico enumerados en el anexo a través del punto de acceso nacional establecido de conformidad con el artículo 3 serán públicamente accesibles para los usuarios de datos, cuando proceda, previamente registrados.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM '') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_12' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A04-P05' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART04' AND legal_reference IS NOT DISTINCT FROM 'Artículo 4, apartado 5' AND source_fact_text IS NOT DISTINCT FROM 'Los usuarios de datos y los titulares de datos colaborarán para garantizar que cualquier inexactitud relacionada con los datos estáticos, históricos y observados sobre desplazamientos y tráfico se notifique sin demora al titular de datos del que proceden los datos.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM '') AS actual
