SELECT 'UNCHANGED_ROW_compliance.source_facts_16' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A05-P03-C' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART05' AND legal_reference IS NOT DISTINCT FROM 'Artículo 5, apartado 3, letra c)' AND source_fact_text IS NOT DISTINCT FROM 'En relación con los datos de desplazamientos y tráfico establecidos en los puntos 2.1 y 2.2 del anexo para las demás partes de la red de transporte de la Unión, a más tardar el 1 de diciembre de 2028.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM '') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_17' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A05-P04' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART05' AND legal_reference IS NOT DISTINCT FROM 'Artículo 5, apartado 4' AND source_fact_text IS NOT DISTINCT FROM 'Cada Estado miembro podrá decidir que los titulares de datos faciliten los datos dinámicos de desplazamientos y tráfico de los diferentes modos de transporte enumerados en el punto 2.3 del anexo, en el territorio de dicho Estado miembro, a través del punto de acceso nacional establecido de conformidad con el artículo 3. En ese caso, los titulares de datos utilizarán SIRI CEN/TS 15531 y versiones posteriores o cualquier formato digital legible por máquina que pueda demostrarse que es plenamente compatible e interoperable con dichas normas y especificaciones técnicas.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'Condicionado a una decisión del Estado miembro; SIRI es una alternativa en este supuesto concreto.') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_18' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A06-P02' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART06' AND legal_reference IS NOT DISTINCT FROM 'Artículo 6, apartado 2' AND source_fact_text IS NOT DISTINCT FROM 'Cuando se produzcan cambios en los datos a que se refiere el apartado 1 del presente artículo, los titulares de datos actualizarán los datos estáticos, históricos, observados y dinámicos pertinentes de desplazamientos y tráfico enumerados en el anexo y los harán accesibles a través del punto de acceso nacional establecido de conformidad con el artículo 3 en un plazo que permita su utilización fiable y efectiva, de conformidad con el artículo 8. Cuando los cambios se conozcan con antelación, los titulares de datos también facilitarán dichas actualizaciones a los usuarios de datos con antelación. Además, corregirán oportunamente cualquier inexactitud que detecten o que les indiquen los usuarios de datos y los usuarios finales.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'El plazo es funcional y no se transforma en una fecha fija.') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_19' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A07-P01' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART07' AND legal_reference IS NOT DISTINCT FROM 'Artículo 7, apartado 1' AND source_fact_text IS NOT DISTINCT FROM 'Previa solicitud, los proveedores de servicios de información sobre desplazamientos comunicarán a otro proveedor de servicios de información sobre desplazamientos los resultados de encaminamiento sobre la base de información estática, histórica, observada y dinámica de desplazamientos y tráfico.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'Condicionado a solicitud.') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_20' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A08-P01' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART08' AND legal_reference IS NOT DISTINCT FROM 'Artículo 8, apartado 1' AND source_fact_text IS NOT DISTINCT FROM 'Los datos de desplazamientos y tráfico enumerados en el anexo y los metadatos correspondientes, incluida la información sobre su calidad, serán accesibles para su intercambio y reutilización dentro de la Unión de forma no discriminatoria, a través del punto de acceso nacional establecido de conformidad con el artículo 3 y en un plazo que permita la reutilización fiable y efectiva de los datos. Esos datos serán exactos, actualizados y se basarán en requisitos mínimos de calidad. A tal efecto, los Estados miembros, en cooperación con las partes interesadas pertinentes de los STI, alcanzarán un acuerdo sobre dichos requisitos mínimos de calidad de los datos.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'Contiene obligaciones diferenciadas para titulares de datos y Estados miembros.') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_21' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A08-P02' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART08' AND legal_reference IS NOT DISTINCT FROM 'Artículo 8, apartado 2' AND source_fact_text IS NOT DISTINCT FROM 'Los datos a que se hace referencia en el apartado 1 deberán reutilizarse de manera neutral sin discriminación o parcialidad alguna con respecto al titular de los datos. Los criterios utilizados para ordenar las opciones de desplazamiento de los diferentes modos de transporte, o combinaciones de estos, o ambas cosas, deberán ser transparentes y no estar basados en ningún factor directa o indirectamente relacionado con la identidad del usuario de datos o del usuario final o, si la hubiera, la consideración comercial relacionada con la reutilización de los datos, y deberán aplicarse de forma no discriminatoria a todos los usuarios de datos o usuarios finales participantes. La primera presentación de itinerario de viaje no deberá inducir a error al usuario final.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'Se preservan varias reglas relacionadas en un candidato, pendientes de revisión de atomicidad.') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_22' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A08-P03' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART08' AND legal_reference IS NOT DISTINCT FROM 'Artículo 8, apartado 3' AND source_fact_text IS NOT DISTINCT FROM 'Cuando se reutilicen los datos estáticos, históricos, observados y dinámicos de desplazamientos y tráfico, se indicará la fuente de dichos datos, si el titular de datos así lo solicita. Se indicará asimismo el intervalo de actualización de los datos estáticos, históricos, observados y, cuando sea posible, dinámicos.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM '') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_23' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A09-P01' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART09' AND legal_reference IS NOT DISTINCT FROM 'Artículo 9, apartado 1' AND source_fact_text IS NOT DISTINCT FROM 'Los Estados miembros evaluarán si los titulares de datos y los proveedores de servicios de información sobre desplazamientos cumplen los requisitos establecidos en los artículos 3 a 8.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'No se trata de una regla de auditoría automática del formato.') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_24' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A09-P02' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART09' AND legal_reference IS NOT DISTINCT FROM 'Artículo 9, apartado 2' AND source_fact_text IS NOT DISTINCT FROM 'A fin de llevar a cabo la evaluación a que se refiere el apartado 1, las autoridades competentes de los Estados miembros podrán solicitar a los titulares de datos y a los proveedores de servicios de información sobre desplazamientos los siguientes documentos: a) una descripción de los datos de desplazamientos y tráfico accesibles a través del punto de acceso nacional, la información sobre su calidad y las condiciones de reutilización de esos datos; b) una descripción de los servicios de información sobre desplazamientos disponibles, incluidas, en su caso, las conexiones con otros servicios; c) una declaración acompañada de los justificantes correspondientes del cumplimiento de los requisitos establecidos en los artículos 3 a 8; d) la licencia o los acuerdos contractuales con proveedores de servicios de información sobre desplazamientos.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'Permiso de solicitud; no se registra como obligación del destinatario sin activación.') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_25' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A10-P01' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART10' AND legal_reference IS NOT DISTINCT FROM 'Artículo 10, apartado 1' AND source_fact_text IS NOT DISTINCT FROM 'A más tardar el 1 de diciembre de 2019, los Estados miembros remitirán a la Comisión un informe sobre las posibles medidas emprendidas para establecer un punto de acceso nacional y sobre las modalidades de su funcionamiento.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'Fecha literal y ámbito explícito. Obligación histórica, vencida.') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_26' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A10-P02' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART10' AND legal_reference IS NOT DISTINCT FROM 'Artículo 10, apartado 2' AND source_fact_text IS NOT DISTINCT FROM 'Los Estados miembros proporcionarán a la Comisión la siguiente información dentro de los informes sobre los progresos realizados a que se refiere el artículo 17, apartado 3, de la Directiva 2010/40/UE: a) los avances realizados en términos de accesibilidad e intercambio de los tipos de datos de desplazamientos y tráfico establecidos en el anexo; b) la cobertura geográfica de los datos que figuran en el anexo accesibles a través del punto de acceso nacional establecido de conformidad con el artículo 3, y su calidad, incluidos los criterios utilizados para definir esa calidad y los medios utilizados para supervisarla; c) la conexión de servicios de información sobre desplazamientos; d) los resultados de la evaluación del cumplimiento a que se refiere el artículo 9, apartado 1; y e) cuando proceda, una descripción de los cambios en el punto de acceso nacional establecido de conformidad con el artículo 3.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'La periodicidad y el contexto del informe remiten a otra norma; NEEDS_REVIEW.') AS actual
UNION ALL
SELECT 'UNCHANGED_ROW_compliance.source_facts_27' AS test, 1 AS expected, (SELECT count(*) FROM compliance.source_facts WHERE source_fact_id IS NOT DISTINCT FROM 'EU-2017-1926-SF-A04-P01-SPATIAL' AND source_document_id IS NOT DISTINCT FROM 'EU-REG-2017-1926' AND source_provision_id IS NOT DISTINCT FROM 'EU-2017-1926-ART04' AND legal_reference IS NOT DISTINCT FROM 'Artículo 4, apartado 1, letra c)' AND source_fact_text IS NOT DISTINCT FROM 'En relación con la red espacial, los requisitos establecidos en el artículo 7 de la Directiva 2007/2/CE.' AND source_version_date IS NOT DISTINCT FROM '2024-03-04' AND source_uri IS NOT DISTINCT FROM 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02017R1926-20240304' AND notes IS NOT DISTINCT FROM 'Remisión a otro acto; se conserva sin interpretarlo.') AS actual
UNION ALL
