SELECT 'FINAL_UNIVERSE_IDS' AS test, 48 AS expected, (SELECT count(DISTINCT final_review_id) FROM read_csv('03_Compliance/reports/phase_2/materialization/REQUIREMENTS_MATERIALIZATION_INPUT.csv',header=true,all_varchar=true)) AS actual
UNION ALL
SELECT 'ALL_48_TRACEABLE' AS test, 48 AS expected, (SELECT count(*) FROM read_csv('03_Compliance/reports/phase_2/materialization/REQUIREMENTS_MATERIALIZATION_INPUT.csv',header=true,all_varchar=true) u JOIN read_csv('03_Compliance/reports/phase_2/materialization/REQUIREMENT_ID_MAP.csv',header=true,all_varchar=true) m USING(final_review_id) JOIN compliance.requirements r USING(requirement_id) JOIN compliance.source_facts f ON u.source_fact_id=f.source_fact_id WHERE r.source_document_id=u.source_document_id AND r.source_provision_id=u.source_provision_id AND f.source_document_id=u.source_document_id AND f.source_provision_id=u.source_provision_id) AS actual
UNION ALL
