UNION ALL
SELECT 'SPLIT_CHILDREN' AS test, 5 AS expected, (SELECT count(*) FROM read_csv('03_Compliance/reports/phase_2/materialization/REQUIREMENT_ID_MAP.csv',header=true,all_varchar=true) m JOIN compliance.requirements r USING(requirement_id) WHERE final_review_id IN ('G2-032-A','G2-032-B','G2-037-A','G2-037-B','G2-037-C')) AS actual
UNION ALL
SELECT 'PARTIAL_PERSISTED' AS test, 7 AS expected, (SELECT count(*) FROM compliance.requirements WHERE json_extract_string(try_cast(notes AS JSON),'$.gate_2.dependency_blocking_level')='PARTIAL' AND json_extract_string(try_cast(notes AS JSON),'$.external_instrument_interpreted')='false') AS actual
UNION ALL
SELECT 'FUNCTIONAL_NO_FIXED_DATE' AS test, 0 AS expected, (SELECT count(*) FROM read_csv('03_Compliance/reports/phase_2/materialization/REQUIREMENTS_MATERIALIZATION_INPUT.csv',header=true,all_varchar=true) u JOIN read_csv('03_Compliance/reports/phase_2/materialization/REQUIREMENT_ID_MAP.csv',header=true,all_varchar=true) m USING(final_review_id) JOIN compliance.requirements r USING(requirement_id) LEFT JOIN compliance.deadlines d USING(requirement_id) WHERE u.temporal_type IN ('FUNCTIONAL_TIME_REQUIREMENT','EXTERNAL_SCHEDULE_REFERENCE') AND (r.deadline_date IS NOT NULL OR d.deadline_id IS NOT NULL)) AS actual
UNION ALL
SELECT 'NO_AUTOMATIC_CONCLUSION' AS test, 0 AS expected, (SELECT count(*) FROM compliance.requirements WHERE is_auditable IS DISTINCT FROM FALSE OR json_extract_string(try_cast(notes AS JSON),'$.legal_conclusion_allowed')='true') AS actual
UNION ALL
SELECT 'NO_INFERRED_GTFS' AS test, 0 AS expected, (SELECT count(*) FROM compliance.requirements WHERE contains(upper(description),'GTFS')) AS actual
) SELECT test, CASE WHEN expected=actual THEN 'PASS' ELSE 'FAIL' END AS status, expected, actual FROM checks ORDER BY test;
